CREATE OR REPLACE FUNCTION public.people_effective_settings(t uuid,v uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE mode text;located boolean;BEGIN IF auth.uid() IS NOT NULL AND NOT(public.user_has_tenant(auth.uid(),t) OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Tenant access required';END IF; SELECT coalesce((SELECT values->>'approvals' FROM public.people_settings WHERE tenant_id=t AND venue_id=v),(SELECT values->>'approvals' FROM public.people_settings WHERE tenant_id=t AND venue_id IS NULL),'owner_run') INTO mode; IF mode NOT IN ('owner_run','managed','strict') THEN mode:='owner_run';END IF; SELECT latitude IS NOT NULL AND longitude IS NOT NULL INTO located FROM public.venues WHERE tenant_id=t AND id=v; RETURN jsonb_build_object('rota',true,'clock_in',CASE WHEN coalesce(located,false) THEN 'venue_phone' ELSE 'off' END,'pay_hours','rota','leave_requests',true,'sick_notes',true,'staff_app',false,'payslips',false,'managers_change_pay',true,'reliability',EXISTS(SELECT 1 FROM public.hr_attendance WHERE tenant_id=t AND (v IS NULL OR venue_id=v) AND clock_in IS NOT NULL),'approvals',mode,'flag_lateness',false,'lateness_minutes',15,'flag_extra_hours',false,'extra_hours_minutes',30); END $$;
ALTER TABLE public.stock_locations ADD COLUMN tenant_id uuid REFERENCES public.tenants(id), ADD COLUMN venue_id uuid REFERENCES public.venues(id);
UPDATE public.stock_locations l SET tenant_id=v.tenant_id,venue_id=v.id FROM public.venues v WHERE v.name=l.venue AND (SELECT count(*) FROM public.venues x WHERE x.name=l.venue)=1;
ALTER TABLE public.bani_accounting_examples ADD COLUMN disabled_at timestamptz;
CREATE OR REPLACE FUNCTION public.settings_edit_accounting_example(t uuid,i uuid,r text,forget boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.user_has_tenant(auth.uid(),t) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accounting administrator required';END IF; UPDATE public.bani_accounting_examples SET reason=r,disabled_at=CASE WHEN forget THEN now() ELSE disabled_at END WHERE tenant_id=t AND id=i; IF NOT FOUND THEN RAISE EXCEPTION 'Example not found';END IF; INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'learning_review','bani_accounting_examples',i::text,jsonb_build_object('forgotten',forget)); END $$;
REVOKE ALL ON FUNCTION public.settings_edit_accounting_example(uuid,uuid,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.settings_edit_accounting_example(uuid,uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.settings_category_account(t uuid,k text,i uuid,a uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n text; BEGIN IF NOT public.user_has_tenant(auth.uid(),t) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accounting administrator required';END IF; IF NOT EXISTS(SELECT 1 FROM public.chart_of_accounts WHERE id=a AND tenant_id=t AND is_active) THEN RAISE EXCEPTION 'Choose an active account';END IF; IF k='expense' THEN UPDATE public.expense_categories SET default_account_id=a WHERE id=i AND tenant_id=t RETURNING name INTO n; ELSIF k='cash' THEN UPDATE public.petty_cash_classifications SET gl_account_id=a WHERE id=i AND tenant_id=t RETURNING name INTO n; ELSIF k='accounting' THEN SELECT name INTO n FROM public.accounting_categories WHERE id=i AND tenant_id=t; ELSE RAISE EXCEPTION 'Unknown category';END IF; IF n IS NULL THEN RAISE EXCEPTION 'Category not found';END IF; INSERT INTO public.account_mapping_rules(tenant_id,rule_type,match_key,account_id,notes) VALUES(t,CASE k WHEN 'accounting' THEN 'invoice_expense' WHEN 'cash' THEN 'petty_cash_category' ELSE 'expense_category' END,n,a,'Accepted in Settings') ON CONFLICT(tenant_id,rule_type,match_key) DO UPDATE SET account_id=excluded.account_id; END $$;
REVOKE ALL ON FUNCTION public.settings_category_account(uuid,text,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.settings_category_account(uuid,text,uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.settings_accounting_defaults() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.enabled:=true;NEW.ask_above:=NULL;RETURN NEW;END $$;
CREATE TRIGGER settings_accounting_defaults BEFORE INSERT OR UPDATE ON public.bani_accounting_settings FOR EACH ROW EXECUTE FUNCTION public.settings_accounting_defaults();
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bani_accounting_commit'; d:=replace(d,' OR NOT s.enabled','');d:=replace(d,'IF s.ask_above IS NOT NULL AND r.amount>s.ask_above THEN RAISE EXCEPTION ''Above your limit'';END IF;','');d:=replace(d,'WHERE tenant_id=r.tenant_id AND conflict_with','WHERE disabled_at IS NULL AND tenant_id=r.tenant_id AND conflict_with');EXECUTE d; SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='bani_accounting_wake';IF d IS NOT NULL THEN d:=replace(d,'NOT enabled OR ','');EXECUTE d;END IF; END $$;
COMMENT ON COLUMN public.bani_accounting_settings.enabled IS 'DEPRECATED: always treated as true; evidence and pause checks remain'; COMMENT ON COLUMN public.bani_accounting_settings.ask_above IS 'DEPRECATED: always treated as null'; COMMENT ON TABLE public.people_settings IS 'Approvals only; feature keys are retained but ignored';